// For non-multipart messages, the entire message minus headers is encoded.
if (!m_isMultipart && !m_partIsSMIME && m_base64part) {
  Base64Decode(buf);
  outLength = buf.Length();
  m_base64part = false;
}

// Process aggregated HTML.
if (!m_isMultipart && m_partIsHtml) {
  StripHtml(buf);
  outLength = buf.Length();
}
